$_ADMINLANG['marketConnect']['socialbee']['about']['author'] = "—— SocialBee 首席执行官 Ovi Negrean";
$_ADMINLANG['marketConnect']['socialbee']['about']['p1'] = "SocialBee 是一款一体化社交媒体管理工具，让用户能够在一个平台上向多个社交媒体网络分享内容。您可以设定发布计划、分享内容、分析表现，并与粉丝互动。";
$_ADMINLANG['marketConnect']['socialbee']['about']['p2'] = "SocialBee 的创立初衷是简化各种规模企业的社交媒体管理。自 2016 年推出以来，该平台已发展成为一款强大的工具，让用户能够在一个平台上跨多个平台创建、排期、分析内容并与受众互动。凭借对易用设计的重视以及基于类别的排期和分析等强大功能，SocialBee 深受创业者、营销人员和代理机构的信赖，帮助他们优化社交媒体表现并与受众建立有意义的联系。";
$_ADMINLANG['marketConnect']['socialbee']['about']['quote'] = "\"在 SocialBee，我们的使命是帮助企业无需为应付多个工具而烦恼，就能在社交媒体上取得成功。我们深受全球数千用户的信赖，将强大的功能与客户至上的理念相结合，确保您获得成功。无论您是刚刚起步，还是管理着大量社交媒体账号，SocialBee 都会在每一步为您提供帮助。\"";
$_ADMINLANG['marketConnect']['socialbee']['about']['title'] = "关于我们";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h1'] = "使用 SocialBee 可以管理哪些社交媒体平台？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h2'] = "SocialBee 用户可以获得哪些支持方式？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h3'] = "SocialBee 的代理机构方案与常规 Pro 方案有何不同？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h4'] = "SocialBee 的服务器位于哪里？SocialBee 的数据存储在哪里？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h5'] = "我为什么要销售社交媒体管理工具？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h6'] = "企业会为社交媒体工具付费吗？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q1'] = "您可以管理和排期适用于 Facebook、Instagram、Threads、X™（原 Twitter™）、LinkedIn、Pinterest、Google Business Profile™、TikTok、YouTube™ 和 Bluesky 等热门平台的内容。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q2'] = "用户可以通过聊天、<a href=\"mailto:hello@socialbee.com\">电子邮件</a>、<a href=\"https://socialbee.com/calendar\">电话</a>以及内容丰富的<a href=\"https://help.socialbee.com\">知识库</a>获取 SocialBee 的帮助。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q3'] = "代理机构方案（Pro50、Pro100 和 Pro150）的功能与 Pro 方案相同。主要区别在于可连接的社交媒体资料数量、工作区数量以及可添加到工作区的用户数量：";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q4'] = "SocialBee 的服务器位于欧洲的爱尔兰。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q5'] = "销售 SocialBee 这样的社交媒体管理工具，可以让您抓住社交媒体营销解决方案日益增长的需求。中小型企业需要工具来打理其社交媒体资料、节省时间并提升互动——这为像您这样的经销商创造了强劲的市场。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q6'] = "是的，中小型企业正在快速投资社交媒体工具以管理其社交媒体形象。作为使用最广泛的营销渠道之一，社交媒体有助于业务增长，企业也乐于投资可靠的工具来帮助其达成目标。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p1'] = "SocialBee 与 Canva、Unsplash 和 GIPHY 集成，让您可以轻松为帖子创建和挑选视觉素材。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p2'] = "借助 AI 在数秒内生成文案和图片，并可访问 1,000 多个预设提示词以节省时间。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p3'] = "尝试图片、视频、轮播、快拍和 Reels 等不同帖子类型，找出最能打动受众的形式。";
