$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['asterisk'] = "基于年收入 50 万美元的网站计算，不含营销活动旺季。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p1'] = "WebPros 旗下品牌服务超过 3300 万用户和 8500 万个域名。借助行业领导者的专业能力，提供 360 Monitoring！";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p2'] = "360 Monitoring 提供前沿的内部与外部系统监控，具备可配置仪表盘、个性化告警以及与主流数据库和服务器技术的无缝集成。依托 cPanel®、Plesk® 和 WHMCS 等强势品牌，它是市场上最全面的监控解决方案。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p3'] = "在线率对您的客户而言就是金钱：即使在线率达到 98%，一个年收入 50 万美元的网站每年仍可能因停机损失 1 万美元*！借助 360 Monitoring，您的客户可以确保访客获得最佳性能、避免代价高昂的停机，并主动解决可能影响业务的问题。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['subtitle'] = "来自 WebPros 的网站与服务器监控";
