$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a10a']['i2'] = "借助高级指标和告警最大化在线率。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a10a']['i3'] = "在潜在问题影响网站访客之前将其解决。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a10a']['i4'] = "通过全站检查提升可见性。";
