$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a10a']['p1'] = "借助 360 Monitoring，您的客户可以：";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a11a'] = "全站检查可保护客户的线上形象。它会抓取整个网站，以检测并警告失效链接、损坏图片、JavaScript 错误，甚至 Google® Fonts 的非法使用。";
