$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a11b']['i4'] = "关于错误或网站故障的警告。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a11b']['p1'] = "全站检查包括：";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a12a'] = "抓取深度是指抓取工具在一次抓取中搜索并分析问题的 URL 数量。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a13a'] = "360 Monitoring 会优先处理已开通此功能客户的抓取任务，优先于未开通客户的抓取任务。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1a'] = "网站监控是一项自动化服务，会按固定间隔（依方案不同，每 1、5 或 10 分钟）对网站执行检测。这些检测可发现客户网站当前及潜在的问题。一旦检测到问题，360 Monitoring 会发送告警并记录该问题以供后续分析。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1b']['i1'] = "停机";
