$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1b']['p1'] = "网站监控包括对以下项目的监控：";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a2a'] = "当某个监控探测点检测到停机时，360 Monitoring 会立即尝试从另外五个位置进行核实，从而帮助确保不会发出误报。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a3a'] = "性能监控工具和流程通过监控 CPU 使用率、内存消耗、磁盘使用率、输入/输出（I/O）性能和网络在线率等系统资源，来检查系统运行状况。360 Monitoring 会跟踪所有这些指标，以确保一切按预期运行。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a4a'] = "性能监控对于在性能问题影响最终用户体验之前将其识别出来至关重要。其对系统资源的分析结果还能让客户主动规划服务器未来的容量需求——包括向您购买更多主机服务！";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a5a'] = "借助 SSL 监控，客户可以轻松跟踪 SSL 证书并在全球范围内规划到期事宜，确保无缝的证书管理。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a6a'] = "您的客户可以从世界任何地方监控网站或服务器，监控节点覆盖澳大利亚、加拿大、芬兰、法国、德国、日本、墨西哥、荷兰、瑞典、英国和美国。";
