$_ADMINLANG['marketConnect']['xoviNow']['about']['h1'] = "XOVI NOW";
$_ADMINLANG['marketConnect']['xoviNow']['about']['h2'] = "关于 XOVI NOW（产品历程）";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p1'] = "企业需要专业的知识和合适的 SEO 工具，才能让其网站登上 Google® 搜索结果的榜首。没有关键词研究、网站分析和对竞争对手的了解，为产品和服务建立曝光度是无法想象的。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p2'] = "借助合适的 SEO 工具，中小企业可以轻松完成这些任务，从而创建出高质量的内容，推动并支持其商业网站的搜索引擎优化。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p3'] = "XOVI NOW 是专为中小企业打造的。作为 SEO 专家，我们与众多企业主进行了交流，评估了大量商业网站的缺陷与优势，并运用自身的 SEO 专业知识，设计出一款让所有人都能驾驭复杂 SEO 的产品。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p4'] = "XOVI NOW 让中小企业无需聘请 SEO 专家或超支预算，就能找到相关关键词、优化现有内容并撰写新的博客文章。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p5'] = "当您的客户选择 XOVI NOW 时，他们就选择了顺畅的入门体验和分步指导，帮助他们随着时间推移获得越来越高的曝光度。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p6'] = "XOVI NOW 是 WebPros 扩展产品家族的最新成员，于 2022 年 2 月推出，提供极富现代感的关键词、排名跟踪和竞争对手分析工具。XOVI 作为 WebPros 旗下公司，是 SEO 行业中的知名品牌，拥有 13 年以上的经验，也是领先的搜索引擎优化 SaaS 开发商。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p7'] = "WebPros 提供最具创新性的技术来推动数字世界的发展。我们汇集各种产品和解决方案，帮助企业在线搭建、运营和成长。我们的产品帮助管理服务器、网站、计费和在线营销。WebPros 拥有一支专门的 SEO 专家团队，参与了 XOVI NOW 的实现，并投入了数月的研究，以找到面向中小企业和 SEO 初学者的合适方法。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1a'] = "既有的 SEO 产品通过提供海量功能来面向 SEO 专家和技术型用户，而 XOVI NOW 的愿景是成为搜索引擎优化行业的“网站搭建工具”式产品。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1b'] = "XOVI NOW 易于使用和理解。它提供恰当的指导与功能组合，让客户可以逐步成长。由于中小企业对价格较为敏感，XOVI NOW 以极具竞争力的定价保持吸引力，同时不牺牲产品品质。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2a'] = "XOVI NOW 是一款 SaaS 解决方案。使用 XOVI NOW 无需其他 WebPros 产品或扩展，也无需自己的服务器。XOVI NOW 完全独立运行，可用于托管在全球任何地方的任何网站。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2b'] = "这也意味着您可以用任何电脑、任何浏览器，只需登录您的账号即可访问 XOVI NOW。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a3a'] = "每位网站所有者都知道在互联网上获得曝光有多么困难。借助 XOVI NOW，我们提供合适的功能来优化网站的可见性。通过抓取我们的数据库为您的业务找到合适的关键词，按周或按天跟踪您的排名（取决于您的产品级别），优化现有或新内容，并检查您的网站是否存在阻碍您获得更好 Google® 排名的技术问题。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a4a'] = "我们全力支持经销商并为其提供协助。您的客户应先联系您，如果您无法给出满意的答复，我们会 100% 在此为您提供尽可能快速的帮助。只需通过<a href=\"https://support.xovinow.com/\" class=\"autoLinked\">XOVI NOW 工单系统</a>联系我们，我们的支持人员将很乐意为您提供帮助。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a5a'] = "项目基于特定 URL（通常是您客户的网站）建立，并会自动创建站点审计（通过网站扫描来识别技术问题）。您的客户只需按照我们的引导向导点击操作，即可创建项目。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6a'] = "完全访问权限账号在 XOVI NOW 产品内拥有完整的管理权限。您可以更改、编辑和添加任何内容（例如关键词、项目或任务）。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6b'] = "只读账号可以访问 XOVI NOW 并查看产品提供的所有 SEO 洞察，但无法编辑项目的任何内容。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7a'] = "站点审计会扫描网站的技术实现，为在 Google® 和其他搜索引擎中获得更好排名打下基础。该工具允许您为每个项目分析最多 1 万个页面/URL（XOVI NOW Starter 级别为每个项目 500 个页面）。扫描结果会自动添加到产品内的顾问工具中，并针对每个问题生成精确的任务。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7b'] = "扫描一个项目所需的时间很大程度上取决于页面/URL 的数量。较小的网站只需几分钟即可完成扫描；较大的在线商店则可能需要数小时才能彻底分析完毕。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8a'] = "该产品主要面向对搜索引擎优化没有了解或了解甚少的 SEO 初学者。如前所述，XOVI NOW 是专为中小企业设计的，并在此目标群体中获得了非常积极的评价。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8b'] = "通过 Pro 级别，我们提供了一个非常适合小型代理机构的选项。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8c'] = "凭借其功能组合以及超过 1 亿关键词的数据库，XOVI NOW 也非常适合进阶的 SEO 用户。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9a'] = "将 XOVI NOW 与 SEMrush 相比较，就像拿苹果和橘子作比较，两者之间并无优劣之分。SEMrush 是一款面向专业 SEO 营销人员的产品，拥有 12 年以上的经验——它们针对不同需求提供不同产品，不能被称为一体化工具。其用户体验是为进阶用户打造的，功能组合对 SEO 初学者来说过于庞杂。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9b'] = "SEMrush 是 SEO 专家和经验丰富的营销经理的正确选择，而 XOVI NOW 则是初学者以及需要在成功之路上获得更多指导的用户的最佳选择。像引导向导和 SEO 顾问这样的功能，在已有的成熟产品中是找不到的。如果您的客户需要一款非常适合中小企业的产品，XOVI NOW 就是不二之选。";
